                "EventSource",
                "Favicon",
                "Font",
                "Form",
                "Frame",
                "Image",
                "Import",
                "Manifest",
                "Ping",
                "PluginData",
                "PluginResource",
                "Prefetch",
                "Resource",
                "Script",
                "ServiceWorker",
                "SharedWorker",
                "Stylesheet",
                "Track",
                "Video",
                "Worker",
