// Group exported functions under \`ill.*\` so the build code can reference them naturally.
const ill = {
    slide1Illustration,
    slide2Illustration,
    slide3Illustration,
    slide4Illustration,
    slide5Illustration,
    slide6Illustration,
    slide8FounderPortrait,
};
// =============================================================================
// END INLINED ILLUSTRATIONS
