  const quarters = ["Y2 Q3", "Y2 Q4", "Y3 Q1", "Y3 Q2", "Y3 Q3", "Y3 Q4",
                    "Y4 Q1", "Y4 Q2", "Y4 Q3", "Y4 Q4", "Y5 Q1", "Y5 Q2"];
  const tlX = MARGIN_X;
  const tlW = W - 2 * MARGIN_X;
  const slotW = tlW / quarters.length;
  const barY = timelineY + 0.4;
