  const platY = silosY + silosH + 0.05;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: silosX - 0.1, y: platY, w: 5 * silosW + 4 * silosGap + 0.2, h: 0.35,
    fill: { color: C.cardLt }, line: { color: C.ink, width: 0.75 },
  });
