  s.addText([{"text": "Designed to disappear into the classroom. No microphones to clip on, no cameras to aim, no software to configure mid-period.", "options": {"fontSize": 22.5, "color": "5C6B63", "fontFace": "-apple-system", "align": "left", "lineSpacingMultiple": 1.4}}], {"x": 1.0417, "y": 2.6841, "w": 12.875, "h": 0.9167, "shape": pptx.ShapeType.rect, "margin": 2.0, "fill": {"type": "none"}, "line": {"type": "none"}, "valign": "top", "shrinkText": true});
