  s.addText([{"text": "A wall-mounted or desktop unit with far-field mics picks up the teacher and student questions clearly from across the room.", "options": {"fontSize": 15.75, "color": "2A3D33", "fontFace": "-apple-system", "align": "left", "lineSpacingMultiple": 1.4}}], {"x": 1.9583, "y": 5.3742, "w": 7.6821, "h": 0.654, "shape": pptx.ShapeType.rect, "margin": 2.0, "fill": {"type": "none"}, "line": {"type": "none"}, "valign": "top", "shrinkText": true});
