  const hdrStyle = { fill: { color: C.cardHead }, color: C.accent, bold: true,
                     fontFace: F.sans, fontSize: 14, align: "center", valign: "middle" };
  const rowHdrStyle = { fill: { color: C.cardHead }, color: C.white, bold: true,
                        fontFace: F.sans, fontSize: 14, align: "center", valign: "middle" };
