  s2.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: yp, w: 0.06, h: 0.85, fill: { color: C.accent } });
  s2.addText(item.title, { x: 0.85, y: yp + 0.1, w: 8.3, h: 0.3, fontSize: 16, fontFace: "Calibri", color: C.accent, bold: true, margin: 0 });
