const pptxgen = require("pptxgenjs");

const pres = new pptxgen();

// ---------- Layout: 13.333" x 7.5" (16:9 widescreen) ----------
pres.defineLayout({ name: "CUSTOM_WIDE", width: 13.333, height: 7.5 });
