pres.author = "Research Desk";

// ---------- Palette ----------
const BG       = "0B0B0B";   // deep near-black
const FG       = "FFFFFF";   // white
const MUTED    = "8A8A8A";   // gray muted text
const DIM      = "555555";   // dim lines
const GREEN    = "7FE27E";   // primary green accent (bright)
