const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_WIDE"; // 13.333 x 7.5
pres.title = "Prediction Markets Investment Memo";
pres.author = "J.P. Morgan \u2014 Associate Review";

