  s9.addText("A phased approach to enterprise-wide deployment across Houston Methodist.", { x: 0.8, y: 0.85, w: 8.4, h: 0.3, fontSize: 13, fontFace: "Calibri", italic: true, color: GRY, margin: 0 });

  // Horizontal timeline line
