    catAxisLabelFontSize: 9, valAxisLabelFontSize: 8,
    valGridLine: { color: C.lightGray, size: 0.5 }, catGridLine: { style: "none" },
    showLegend: true, legendPos: "b", legendFontSize: 8, legendColor: C.dkGray, legendFontFace: F,
