    showLegend: true, legendPos: "b", legendFontSize: 7, legendColor: C.dkGray, legendFontFace: F,
    showTitle: true, title: "Separation Reasons (Q1)", titleColor: C.dkGray, titleFontSize: 9, titleFontFace: F,
