  s.addShape("line", { x: cx - 0.25, y: cy - 1.2, w: 0.25, h: 0.18, line: { color: C.ink, width: 1 } });
  s.addShape("line", { x: cx,      y: cy - 1.02, w: 0.25, h: -0.18, line: { color: C.ink, width: 1 } });
