  // Tail (long curve approximated by rotated ellipse + tip)
  s.addShape("ellipse", { x: bx - 1.3, y: by + 0.4, w: 1.6, h: 0.25,
    fill: { color: "1A0E05" }, line: { color: "1A0E05" }, rotate: -10 });

