    // Title
    addBody(s, c.title, c.x, 8.83, 5.44, 0.52, {
      fontSize: 31.5, color: COLOR.ink, align: "center",
    });
    // Caption
    addBody(s, c.caption, c.x, 9.44, 5.44, 0.40, {
      fontSize: 19.5, italic: true, color: COLOR.muted, align: "center",
    });
