  slide.addText('FIFTEEN WINTERS, ONE METHOD', { x: 0.75, y: 10.3802, w: 5.095, h: 0.3781, align: 'left', valign: 'top', margin: [2.0, 2.0, 2.0, 2.0], isTextBox: true, fontSize: 18.0, charSpacing: 2.16, color: 'F4F1EA', fontFace: 'Arial' });
