  slide.addText([{ text: 'Engagement power over broadcasting', options: { fontSize: 21, bold: true, color: '034694', fontFace: 'Century Gothic' } }], { x: 9.1017, y: 3.95, w: 3.3, h: 0.95, margin: 0, valign: 'middle' });
